  const candidates = [source, ...[...source.matchAll(/```(?:json)?\s*([\s\S]*?)```/gi)].map((m) => m[1].trim())];
  for (const candidate of candidates) { try { json = Math.max(json, collectionSize(JSON.parse(candidate))); } catch { /* not JSON */ } }
